namespace BuzzerApp.Core.Domain;

/// <summary>A round that reached the locked phase (D28). The id is generated by Core's engine, not the database.</summary>
public class Round
{
    public Guid Id { get; set; }
    public int EventId { get; set; }
    public DateTimeOffset StartedAt { get; set; }
    public DateTimeOffset? LockedAt { get; set; }
    public DateTimeOffset? EndedAt { get; set; }

    public ICollection<BuzzRecord> Buzzes { get; } = new List<BuzzRecord>();
}
